#!/bin/sh
# Use the GLES AssetBundle generated by the shader tools.
set -eu
case "$#:${1:-}" in
    1:--verify-only) package=0 ;;
    2:*) package=1 ;;
    *) printf '%s\n' 'Usage: stage_candidate.sh --verify-only | VERIFIED_GLES_BUNDLE OUTPUT_ZIP' >&2; exit 2 ;;
esac
WORKSPACE_ROOT=$(CDPATH='' cd -- "$(dirname -- "$0")/../.." && pwd)
. "$WORKSPACE_ROOT/tools/rain-meadow/env.sh"
cd "$WORKSPACE_ROOT"

source=$RAIN_MEADOW_SOURCE
runtime=tools/rain-meadow/runtime
il=tools/rain-meadow/il
mkdir -p work/rain-meadow
run=$(mktemp -d work/rain-meadow/candidate.XXXXXX)
printf '%s\n' "Staging in $run"
sha256sum "$RAIN_MEADOW_GAME_MANAGED/Assembly-CSharp.dll" \
    "$RAIN_MEADOW_GAME_MANAGED/HOOKS-Assembly-CSharp.dll" > "$run/game-inputs.sha256"
sh tools/rain-meadow/bootstrap_build.sh
il_changed=0
sh "$il/verify_targets.sh" "$run/game-il.tsv" || il_changed=1

python3 -IB "$il/stage_il.py" "$source" "$run/il-overlay"
python3 -IB "$runtime/stage_lan.py" "$source" "$run/lan-overlay"
mkdir -p "$run/overlay"
cp -r "$run/il-overlay/." "$run/overlay/"
cp -r "$run/lan-overlay/." "$run/overlay/"
steam_probe=${RAIN_MEADOW_STEAM_PROBE:-0}
case "$steam_probe" in
    0) RAIN_MEADOW_STEAM_PROBE_DEPS= ;;
    1)
        sh tools/rain-meadow/steam/build_probe.sh
        RAIN_MEADOW_STEAM_PROBE_DEPS=work/rain-meadow/steam/dependencies
        ;;
    *) printf '%s\n' 'RAIN_MEADOW_STEAM_PROBE must be 0 or 1' >&2; exit 2 ;;
esac
export RAIN_MEADOW_STEAM_PROBE_DEPS

if ! RAIN_MEADOW_OVERLAY="$run/overlay" RAIN_MEADOW_BUILD_DIR="$run/build" sh tools/rain-meadow/build.sh > "$run/build.log" 2>&1; then
    tail -n 60 "$run/build.log" >&2
    exit 1
fi
plugin="$run/build/bin/Rain Meadow.dll"
sh "$il/replay.sh" "$plugin" > "$run/replay.tsv"
if ! awk -F '\t' 'NF && $2 != "changed" { print; bad=1 } END { exit (NR==0 || bad) }' "$run/replay.tsv"; then
    printf '%s\n' "Selected IL replay failed. See $run/replay.tsv." >&2
    exit 1
fi
if ! sh "$il/replay.sh" --startup "$plugin" > "$run/startup-replay.tsv" 2> "$run/startup-replay.log"; then
    cat "$run/startup-replay.tsv" "$run/startup-replay.log" >&2
    exit 1
fi
if ! sh "$il/replay.sh" --jit-all "$plugin" "$run/hook-jit.tsv" > "$run/hook-jit.log" 2>&1; then
    if [ -f "$run/hook-jit.tsv" ]; then
        awk -F '\t' 'NR>1 && $4 != "compiled"' "$run/hook-jit.tsv" >&2
    fi
    tail -n 40 "$run/hook-jit.log" >&2
    printf '%s\n' "Mono hook-chain validation failed. See $run/hook-jit.tsv and $run/hook-jit.log." >&2
    exit 1
fi
if [ "$il_changed" -ne 0 ]; then
    printf '%s\n' "Review $run/game-il.tsv even if the offline replay passed." >&2
    exit 1
fi
awk 'END { print NR " targeted IL replays passed" }' "$run/replay.tsv"
awk 'END { print NR - 1 " IL hook registrations compiled" }' "$run/hook-jit.tsv"
printf '%s\n' "Verified plugin: $plugin"
if [ "$package" -eq 0 ]; then
    exit 0
fi
assets=${RAIN_MEADOW_ASSET_SOURCE:-}
if [ -z "$assets" ]; then
    assets=$(python3 -IB tools/rain-meadow/ci_inputs.py upstream)
fi
python3 -IB "$runtime/stage_audio.py" "$assets/Mod" --stage "$run/audio" --decode > "$run/audio.json"
set -- --mod "$assets/Mod" --audio "$run/audio" --shader "$1" --plugin "$plugin" "$2"
if [ -n "${RAIN_MEADOW_MOD_OVERLAY:-}" ]; then
    set -- "$@" --overlay-mod "$RAIN_MEADOW_MOD_OVERLAY"
fi
set -- "$@" --overlay-mod "$source/Mod"
if [ "$steam_probe" -eq 1 ]; then
    sh tools/rain-meadow/steam/stage_dependencies.sh
    if [ "${RAIN_MEADOW_STEAM_SDR:-0}" = 1 ]; then
        set -- "$@" --steam-probe work/rain-meadow/steam/package-input-sdr
    elif [ "${RAIN_MEADOW_STEAM_GAMEPLAY:-0}" = 1 ]; then
        set -- "$@" --steam-probe work/rain-meadow/steam/package-input-gameplay
    else
        set -- "$@" --steam-probe work/rain-meadow/steam/package-input
    fi
fi
python3 -IB tools/rain-meadow/package.py "$@"
